############ 301de9a20553 diff super.c ############
commit 301de9a2055357375a4e1053d9df0f8f3467ff00
Author: Johan Hovold <johan+linaro@kernel.org>
Date:   Thu Jan 19 17:42:53 2023 +0100

    efivarfs: always register filesystem

    The efivar ops are typically registered at subsys init time so that
    they are available when efivarfs is registered at module init time.

    Other efivars implementations, such as Google SMI, exist and can
    currently be built as modules which means that efivar may not be
    available when efivarfs is initialised.

    Move the efivar availability check from module init to when the
    filesystem is mounted to allow late registration of efivars.

    Signed-off-by: Johan Hovold <johan+linaro@kernel.org>
    Signed-off-by: Ard Biesheuvel <ardb@kernel.org>

diff --git a/fs/efivarfs/super.c b/fs/efivarfs/super.c
index f72c529c8ec3..482d612b716b 100644
--- a/fs/efivarfs/super.c
+++ b/fs/efivarfs/super.c
@@ -194,6 +194,9 @@ static int efivarfs_fill_super(struct super_block *sb, struct fs_context *fc)
 	struct dentry *root;
 	int err;

+	if (!efivar_is_available())
+		return -EOPNOTSUPP;
+
 	sb->s_maxbytes          = MAX_LFS_FILESIZE;
 	sb->s_blocksize         = PAGE_SIZE;
 	sb->s_blocksize_bits    = PAGE_SHIFT;
@@ -243,6 +246,9 @@ static void efivarfs_kill_sb(struct super_block *sb)
 {
 	kill_litter_super(sb);

+	if (!efivar_is_available())
+		return;
+
 	/* Remove all entries and destroy */
 	efivar_entry_iter(efivarfs_destroy, &efivarfs_list, NULL);
 }
@@ -256,9 +262,6 @@ static struct file_system_type efivarfs_type = {

 static __init int efivarfs_init(void)
 {
-	if (!efivar_is_available())
-		return -ENODEV;
-
 	return register_filesystem(&efivarfs_type);
 }

############ d86ff3333cb1 diff super.c ############
commit d86ff3333cb1d5f42d8898fb5fdb304e143c0237
Author: Anisse Astier <an.astier@criteo.com>
Date:   Wed May 17 17:38:12 2023 +0200

    efivarfs: expose used and total size

    When writing EFI variables, one might get errors with no other message
    on why it fails. Being able to see how much is used by EFI variables
    helps analyzing such issues.

    Since this is not a conventional filesystem, block size is intentionally
    set to 1 instead of PAGE_SIZE.

    x86 quirks of reserved size are taken into account; so that available
    and free size can be different, further helping debugging space issues.

    With this patch, one can see the remaining space in EFI variable storage
    via efivarfs, like this:

       $ df -h /sys/firmware/efi/efivars/
       Filesystem      Size  Used Avail Use% Mounted on
       efivarfs        176K  106K   66K  62% /sys/firmware/efi/efivars

    Signed-off-by: Anisse Astier <an.astier@criteo.com>
    [ardb: - rename efi_reserved_space() to efivar_reserved_space()
           - whitespace/coding style tweaks]
    Signed-off-by: Ard Biesheuvel <ardb@kernel.org>

diff --git a/fs/efivarfs/super.c b/fs/efivarfs/super.c
index 482d612b716b..e028fafa04f3 100644
--- a/fs/efivarfs/super.c
+++ b/fs/efivarfs/super.c
@@ -13,6 +13,7 @@
 #include <linux/ucs2_string.h>
 #include <linux/slab.h>
 #include <linux/magic.h>
+#include <linux/statfs.h>

 #include "internal.h"

@@ -23,8 +24,44 @@ static void efivarfs_evict_inode(struct inode *inode)
 	clear_inode(inode);
 }

+static int efivarfs_statfs(struct dentry *dentry, struct kstatfs *buf)
+{
+	const u32 attr = EFI_VARIABLE_NON_VOLATILE |
+			 EFI_VARIABLE_BOOTSERVICE_ACCESS |
+			 EFI_VARIABLE_RUNTIME_ACCESS;
+	u64 storage_space, remaining_space, max_variable_size;
+	efi_status_t status;
+
+	status = efivar_query_variable_info(attr, &storage_space, &remaining_space,
+					    &max_variable_size);
+	if (status != EFI_SUCCESS)
+		return efi_status_to_err(status);
+
+	/*
+	 * This is not a normal filesystem, so no point in pretending it has a block
+	 * size; we declare f_bsize to 1, so that we can then report the exact value
+	 * sent by EFI QueryVariableInfo in f_blocks and f_bfree
+	 */
+	buf->f_bsize	= 1;
+	buf->f_namelen	= NAME_MAX;
+	buf->f_blocks	= storage_space;
+	buf->f_bfree	= remaining_space;
+	buf->f_type	= dentry->d_sb->s_magic;
+
+	/*
+	 * In f_bavail we declare the free space that the kernel will allow writing
+	 * when the storage_paranoia x86 quirk is active. To use more, users
+	 * should boot the kernel with efi_no_storage_paranoia.
+	 */
+	if (remaining_space > efivar_reserved_space())
+		buf->f_bavail = remaining_space - efivar_reserved_space();
+	else
+		buf->f_bavail = 0;
+
+	return 0;
+}
 static const struct super_operations efivarfs_ops = {
-	.statfs = simple_statfs,
+	.statfs = efivarfs_statfs,
 	.drop_inode = generic_delete_inode,
 	.evict_inode = efivarfs_evict_inode,
 };
