129: static struct dentry *efivarfs_alloc_dentry(struct dentry *parent, char *name)
130: {
131: 	struct dentry *d;
132: 	struct qstr q;
133: 	int err;
134: 
135: 	q.name = name;
136: 	q.len = strlen(name);
137: 
138: 	err = efivarfs_d_hash(parent, &q);
139: 	if (err)
140: 		return ERR_PTR(err);
141: 
142: 	d = d_alloc(parent, &q);
143: 	if (d)
144: 		return d;
145: 
146: 	return ERR_PTR(-ENOMEM);
147: }
